const body = $input.item.json.body || {};
const level = body.level || 'error';
const message = body.message || 'Unknown error';
const context = body.context || {};
const entry = {
  timestamp: new Date().toISOString(),
  level,
  source: 'supportloop',
  message,
  ...context
};
console.error(JSON.stringify(entry));
return [{ json: entry }];
